INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'crystal-ball', N'紫雾心愿水晶球', N'Violet Wish Globe', NULL, NULL, N'将一个小愿望收进紫雾水晶球，让柔和光晕陪你慢慢把未来说给朋友听。', N'Keep a small wish inside a violet crystal ball and let its soft glow help you share it.', 280000, 28000, N'趣味珍藏', NULL, NULL, NULL, NULL, N'珍藏款', N'#AE8CCF', N'orbit', N'galaxy', NULL, N'gift-art/fluent/crystal-ball.png', N'gift-art/fluent/crystal-ball.png', N'gift-art/fluent/crystal-ball.charm.png', 0, N'mall,chat', 1, 1024);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'satellite', N'遥远问候卫星', N'Faraway Hello Satellite', NULL, NULL, N'让一颗小卫星绕过漫长距离，把此刻的问候稳稳送到彼此的心里。', N'A small satellite that crosses long distances to deliver this hello safely.', 1500000, 150000, N'臻享臻藏', NULL, NULL, NULL, NULL, N'臻藏款', N'#9DB4D4', N'orbit', N'galaxy', NULL, N'gift-art/fluent/satellite.png', N'gift-art/fluent/satellite.png', N'gift-art/fluent/satellite.charm.png', 0, N'mall,chat', 1, 1025);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'earth', N'蔚蓝同心地球', N'Blue Planet, Together', NULL, NULL, N'把共同生活的蓝色星球捧在掌心，愿不同城市的我们也能分享同一份温柔。', N'Hold our shared blue planet in your hands: different cities, the same kindness.', 1620000, 162000, N'臻享臻藏', NULL, NULL, NULL, NULL, N'臻藏款', N'#72BBCA', N'orbit', N'galaxy', NULL, N'gift-art/fluent/earth.png', N'gift-art/fluent/earth.png', N'gift-art/fluent/earth.charm.png', 0, N'mall,chat', 1, 1026);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'ringed-planet', N'星环漫游行星', N'Ringed Wanderer', NULL, NULL, N'沿着柔亮的星环慢慢漫游，给那些聊不完的想象留下一整片夜空。', N'Drift along a glowing ring and leave a whole night sky for the ideas you can’t stop talking about.', 1750000, 175000, N'臻享臻藏', NULL, NULL, NULL, NULL, N'臻藏款', N'#D0B28C', N'orbit', N'galaxy', NULL, N'gift-art/fluent/ringed-planet.png', N'gift-art/fluent/ringed-planet.png', N'gift-art/fluent/ringed-planet.charm.png', 0, N'mall,chat', 1, 1027);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'violin', N'暮色弦语小提琴', N'Twilight Violin', NULL, NULL, N'让木色琴弦替你奏起一段轻柔旋律，陪这场谈话停在恰到好处的温度。', N'Let wooden strings play a soft tune and keep the conversation at just the right warmth.', 160000, 16000, N'趣味珍藏', NULL, NULL, NULL, NULL, N'珍藏款', N'#B78365', N'stars', N'galaxy', NULL, N'gift-art/fluent/violin.png', N'gift-art/fluent/violin.png', N'gift-art/fluent/violin.charm.png', 0, N'mall,chat', 1, 1028);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'love-letter', N'悄悄心意信笺', N'Secret Note', NULL, NULL, N'把一句惦念折进小小信封，让不善言辞的温柔也能被认真看见。', N'Fold a thought of someone into a little envelope, so quiet kindness gets seen.', 1800, 180, N'心意礼物', NULL, NULL, NULL, NULL, N'心意款', N'#DD8D9B', N'hearts', N'heart', NULL, N'gift-art/fluent/love-letter.png', N'gift-art/fluent/love-letter.png', N'gift-art/fluent/love-letter.charm.png', 0, N'mall,chat', 1, 1029);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'oriental-tongxin-knot', N'同心结', N'Heart Knot', NULL, NULL, N'一枚朱红盘长结垂着细金穗，把想说的祝福系在一起；适合送给刚认识的新朋友，也能放在主页作小巧挂件。', N'A red endless knot with fine golden tassels that ties your wishes together. A lovely hello for a new friend, or a small charm for your profile.', 9, 100, N'盛世华章', N'盛世华章', N'盛世华章', N'盛世雅物', N'入门', N'入门款', N'#BE2534', N'hearts', N'heart', N'knot', N'gift-art/oriental/oriental-tongxin-knot.png', N'gift-art/oriental/oriental-tongxin-knot.thumb.png', N'gift-art/oriental/oriental-tongxin-knot.charm.png', 0, N'mall,chat,live,private', 1, 34);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'oriental-lantern', N'灯笼', N'Palace Lantern', NULL, NULL, N'描金宫灯点亮暖黄烛光，沿着夜色缓缓升起；把团圆与平安的心意送到正在聊天的人面前。', N'A gilded palace lantern rising into the night with warm candlelight, carrying wishes for reunion and peace.', 19, 280, N'盛世华章', N'盛世华章', N'盛世华章', N'盛世雅物', N'入门', N'入门款', N'#D44627', N'confetti', N'celebration', N'lantern', N'gift-art/oriental/oriental-lantern.png', N'gift-art/oriental/oriental-lantern.thumb.png', N'gift-art/oriental/oriental-lantern.charm.png', 0, N'mall,chat,live,private', 1, 35);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'oriental-folding-fan', N'折扇', N'Folding Fan', NULL, NULL, N'一柄乌木折扇展开层叠水墨山峦，合拢时留下一缕金色光迹；适合送给喜欢旅行与山水的朋友。', N'An ebony fan that opens onto layered ink-wash mountains and leaves a trail of gold as it closes. For friends who love travel and landscapes.', 39, 520, N'盛世华章', N'盛世华章', N'盛世华章', N'盛世雅物', N'入门', N'入门款', N'#966747', N'stars', N'galaxy', N'fan', N'gift-art/oriental/oriental-folding-fan.png', N'gift-art/oriental/oriental-folding-fan.thumb.png', N'gift-art/oriental/oriental-folding-fan.charm.png', 0, N'mall,chat,live,private', 1, 36);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'oriental-blue-white-porcelain', N'青花瓷', N'Blue-and-White Vase', NULL, NULL, N'白瓷小瓶映着细密青花缠枝纹，旋转间显出柔和釉光；让一份安静的雅意留在好友的礼物收藏里。', N'A small white vase wrapped in delicate blue scrolls, its glaze glowing softly as it turns.', 199, 2600, N'盛世华章', N'盛世华章', N'盛世华章', N'盛世雅物', N'进阶', N'进阶款', N'#386898', N'orbit', N'galaxy', N'porcelain', N'gift-art/oriental/oriental-blue-white-porcelain.png', N'gift-art/oriental/oriental-blue-white-porcelain.thumb.png', N'gift-art/oriental/oriental-blue-white-porcelain.charm.png', 0, N'mall,chat,live,private', 1, 37);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'oriental-phoenix-flight', N'凤凰于飞', N'Phoenixes in Flight', NULL, NULL, N'赤金凤凰舒展羽翼，尾羽如轻柔绸带掠过屏幕；送给并肩前行的人，纪念彼此照亮的一刻。', N'A red-gold phoenix spreads its wings, tail feathers sweeping like silk. For the one walking beside you.', 520, 7800, N'盛世华章', N'盛世华章', N'盛世华章', N'盛世雅物', N'进阶', N'进阶款', N'#C84C42', N'royal', N'crown', N'phoenix', N'gift-art/oriental/oriental-phoenix-flight.png', N'gift-art/oriental/oriental-phoenix-flight.thumb.png', N'gift-art/oriental/oriental-phoenix-flight.charm.png', 1, N'mall,chat,live,private', 1, 38);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'oriental-pipa-song', N'琵琶行', N'Song of the Pipa', NULL, NULL, N'梨花木琵琶立在云纹绸带间，琴弦泛起细碎金芒；把一段无需言说的悠长心绪送进今晚的会话。', N'A pearwood pipa among cloud-pattern ribbons, its strings flickering gold. For feelings that need no words.', 399, 4500, N'盛世华章', N'盛世华章', N'盛世华章', N'盛世雅物', N'进阶', N'进阶款', N'#B28355', N'stars', N'galaxy', N'pipa', N'gift-art/oriental/oriental-pipa-song.png', N'gift-art/oriental/oriental-pipa-song.thumb.png', N'gift-art/oriental/oriental-pipa-song.charm.png', 0, N'mall,chat,live,private', 1, 39);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'oriental-golden-dragon', N'龙腾', N'Soaring Dragon', NULL, NULL, N'鎏金祥龙穿过层叠云海腾空盘旋，龙鳞映着故宫红光；用一份壮阔礼物为朋友的重要时刻喝彩。', N'A gilded dragon circles up through the clouds, scales catching palace-red light. A grand cheer for a big moment.', 2999, 48000, N'盛世华章', N'盛世华章', N'盛世华章', N'盛世雅物', N'豪华', N'豪华款', N'#D29B37', N'royal', N'crown', N'dragon', N'gift-art/oriental/oriental-golden-dragon.png', N'gift-art/oriental/oriental-golden-dragon.thumb.png', N'gift-art/oriental/oriental-golden-dragon.charm.png', 1, N'mall,chat,live,private', 1, 40);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'oriental-nine-ding', N'九鼎', N'Nine Ding', NULL, NULL, N'青铜古鼎承着九重云纹，鼎耳与金边在光束中渐次显现；适合纪念一项稳稳落地的重要成果。', N'A bronze ding rising on nine layers of cloud, its gold rim appearing in the light. To mark a goal reached.', 3999, 60000, N'盛世华章', N'盛世华章', N'盛世华章', N'盛世雅物', N'豪华', N'豪华款', N'#A9783D', N'royal', N'crown', N'ding', N'gift-art/oriental/oriental-nine-ding.png', N'gift-art/oriental/oriental-nine-ding.thumb.png', N'gift-art/oriental/oriental-nine-ding.charm.png', 0, N'mall,chat,live,private', 1, 41);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'oriental-qilin-treasure', N'麒麟送宝', N'Qilin Brings Treasure', NULL, NULL, N'瑞兽麒麟踏着祥云送来一只缀金宝匣，步伐轻快而隆重；把好事临门的祝愿留给特别的伙伴。', N'A qilin trots in on lucky clouds with a gold-trimmed treasure box. Good fortune for someone special.', 5200, 72000, N'盛世华章', N'盛世华章', N'盛世华章', N'盛世雅物', N'豪华', N'豪华款', N'#C88B3F', N'confetti', N'celebration', N'qilin', N'gift-art/oriental/oriental-qilin-treasure.png', N'gift-art/oriental/oriental-qilin-treasure.thumb.png', N'gift-art/oriental/oriental-qilin-treasure.charm.png', 0, N'mall,chat,live,private', 1, 42);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'oriental-landscape-scroll', N'江山如画', N'Rivers and Mountains', NULL, NULL, N'长卷徐徐展开，黛色山峦、云水与金色楼阁在纸上相遇；把眼前的宽阔风景送给愿意同行的人。', N'A long scroll unrolls: dark mountains, clouds, water and golden pavilions. A wide view for someone who travels with you.', 12888, 138000, N'盛世华章', N'盛世华章', N'盛世华章', N'盛世雅物', N'顶级', N'顶级款', N'#887451', N'orbit', N'galaxy', N'scroll', N'gift-art/oriental/oriental-landscape-scroll.png', N'gift-art/oriental/oriental-landscape-scroll.thumb.png', N'gift-art/oriental/oriental-landscape-scroll.charm.png', 0, N'mall,chat,live,private', 1, 43);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'oriental-phoenix-crown', N'凤冠霞帔', N'Phoenix Crown', NULL, NULL, N'点翠凤冠嵌着金珠与红色流苏，霞帔般的柔光在身后舒展；为值得珍惜的喜庆日子添一场华美仪式。', N'A kingfisher-blue phoenix crown with gold beads and red tassels, glowing like a bridal cape. For celebrations worth treasuring.', 18888, 168000, N'盛世华章', N'盛世华章', N'盛世华章', N'盛世雅物', N'顶级', N'顶级款', N'#C59042', N'royal', N'crown', N'crown', N'gift-art/oriental/oriental-phoenix-crown.png', N'gift-art/oriental/oriental-phoenix-crown.thumb.png', N'gift-art/oriental/oriental-phoenix-crown.charm.png', 1, N'mall,chat,live,private', 1, 44);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'oriental-heavenly-craft', N'天工开物', N'Heavenly Craftsmanship', NULL, NULL, N'匠作宝匣汇聚建筑飞檐、青花瓷片与龙凤金纹，层层打开如一座微缩工艺殿堂；献给认真创造生活的人。', N'A master’s box of flying eaves, porcelain and dragon-phoenix gold that opens like a tiny palace of craft. For people who make life with care.', 29999, 200000, N'盛世华章', N'盛世华章', N'盛世华章', N'盛世雅物', N'顶级', N'顶级款', N'#D19B55', N'royal', N'crown', N'craft', N'gift-art/oriental/oriental-heavenly-craft.png', N'gift-art/oriental/oriental-heavenly-craft.thumb.png', N'gift-art/oriental/oriental-heavenly-craft.charm.png', 0, N'mall,chat,live,private', 1, 45);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'oriental-azure-dragon', N'青龙出海', N'Azure Dragon Rises', NULL, NULL, N'青碧灵龙越过墨色海浪，长须与云气带出流动的翠金光；这份四灵藏品象征向新的方向出发。', N'A jade dragon crosses ink-dark waves, trailing green-gold light. A guardian for setting off in a new direction.', 8888, 82000, N'盛世华章', N'盛世华章', N'盛世华章', N'上古四灵', N'豪华', N'豪华款', N'#4A9A91', N'orbit', N'galaxy', N'azure-dragon', N'gift-art/oriental/oriental-azure-dragon.png', N'gift-art/oriental/oriental-azure-dragon.thumb.png', N'gift-art/oriental/oriental-azure-dragon.charm.png', 1, N'mall,chat,live,private', 1, 46);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'oriental-white-tiger', N'白虎踏星', N'White Tiger Among Stars', NULL, NULL, N'银白猛虎踩过深蓝星轨，额间金纹随着步伐闪亮；为勇敢迈出一步的朋友留下利落而坚定的祝福。', N'A silver tiger strides across deep-blue star trails, gold markings shining. For a friend taking a brave step.', 6999, 76000, N'盛世华章', N'盛世华章', N'盛世华章', N'上古四灵', N'豪华', N'豪华款', N'#AEB9C9', N'stars', N'galaxy', N'white-tiger', N'gift-art/oriental/oriental-white-tiger.png', N'gift-art/oriental/oriental-white-tiger.thumb.png', N'gift-art/oriental/oriental-white-tiger.charm.png', 1, N'mall,chat,live,private', 1, 47);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'oriental-vermilion-bird', N'朱雀涅槃', N'Vermilion Rebirth', NULL, NULL, N'朱雀从金红羽焰中展翼而起，细小火羽化作温暖光点；送给刚走过低谷、再次拥抱新开始的人。', N'The vermilion bird rises from red-gold flames. For someone starting again after a hard time.', 9999, 98000, N'盛世华章', N'盛世华章', N'盛世华章', N'上古四灵', N'顶级', N'顶级款', N'#D15036', N'royal', N'crown', N'vermilion-bird', N'gift-art/oriental/oriental-vermilion-bird.png', N'gift-art/oriental/oriental-vermilion-bird.thumb.png', N'gift-art/oriental/oriental-vermilion-bird.charm.png', 1, N'mall,chat,live,private', 1, 48);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'oriental-black-tortoise', N'玄武御天', N'Black Tortoise Shield', NULL, NULL, N'龟蛇相依的玄武浮在深色云台之上，甲纹托起一圈温润的金色屏障；愿所爱之人安稳从容。', N'Tortoise and serpent rest on a dark cloud terrace under a warm golden shield. May the ones you love stay safe.', 9888, 92000, N'盛世华章', N'盛世华章', N'盛世华章', N'上古四灵', N'顶级', N'顶级款', N'#637C79', N'orbit', N'galaxy', N'black-tortoise', N'gift-art/oriental/oriental-black-tortoise.png', N'gift-art/oriental/oriental-black-tortoise.thumb.png', N'gift-art/oriental/oriental-black-tortoise.charm.png', 1, N'mall,chat,live,private', 1, 49);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'oriental-golden-calligraphy', N'一字千金', N'Golden Word', NULL, NULL, N'羊毫笔蘸开浓墨，在宣纸上写出一枚泛金的吉字；为正在努力的朋友送上一点鼓励与文采。', N'A brush writes one lucky character that turns to gold. A little encouragement for a friend working hard.', 29, 380, N'盛世华章', N'盛世华章', N'盛世华章', N'金榜题名', N'入门', N'入门款', N'#A78147', N'stars', N'galaxy', N'calligraphy', N'gift-art/oriental/oriental-golden-calligraphy.png', N'gift-art/oriental/oriental-golden-calligraphy.thumb.png', N'gift-art/oriental/oriental-golden-calligraphy.charm.png', 0, N'mall,chat,live,private', 1, 50);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'oriental-top-scholar', N'高中状元', N'Top Scholar', NULL, NULL, N'绛红状元帽缀着金色花翎，卷轴在旁缓缓展开；祝贺考试、面试或作品发布时的每一份认真准备。', N'A crimson scholar’s hat with gold plumes beside an unrolling scroll. Congratulations on an exam, interview or launch.', 999, 18000, N'盛世华章', N'盛世华章', N'盛世华章', N'金榜题名', N'进阶', N'进阶款', N'#C33E35', N'confetti', N'celebration', N'scholar', N'gift-art/oriental/oriental-top-scholar.png', N'gift-art/oriental/oriental-top-scholar.thumb.png', N'gift-art/oriental/oriental-top-scholar.charm.png', 0, N'mall,chat,live,private', 1, 51);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'oriental-carp-dragon-gate', N'鱼跃龙门', N'Carp Leaps the Gate', NULL, NULL, N'赤金锦鲤冲出浪花跃向汉白玉龙门，水滴化作细碎星点；为迎来转机的好消息送上掌声。', N'A golden carp bursts from the waves toward the dragon gate. Applause for good news and a turning point.', 1888, 30000, N'盛世华章', N'盛世华章', N'盛世华章', N'金榜题名', N'豪华', N'豪华款', N'#D39B54', N'launch', N'rocket', N'carp', N'gift-art/oriental/oriental-carp-dragon-gate.png', N'gift-art/oriental/oriental-carp-dragon-gate.thumb.png', N'gift-art/oriental/oriental-carp-dragon-gate.charm.png', 0, N'mall,chat,live,private', 1, 52);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'oriental-ao-champion', N'独占鳌头', N'First Place', NULL, NULL, N'金鳌踏浪托起高台，卷云环绕如庆典舞台；把这一份荣耀感送给刚取得突破的朋友，纪念真正付出的努力。', N'A golden sea turtle lifts a stage above the waves, ringed by clouds. Honour for a friend who just broke through.', 11999, 112000, N'盛世华章', N'盛世华章', N'盛世华章', N'金榜题名', N'顶级', N'顶级款', N'#B8833E', N'royal', N'crown', N'ao', N'gift-art/oriental/oriental-ao-champion.png', N'gift-art/oriental/oriental-ao-champion.thumb.png', N'gift-art/oriental/oriental-ao-champion.charm.png', 0, N'mall,chat,live,private', 1, 53);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'oriental-midnight-pagoda', N'子时·夜明琉璃', N'Midnight · Glass Pagoda', NULL, NULL, N'子夜的琉璃小塔透出深蓝与金色微光，月影落在塔檐；陪晚睡的人把夜色过得柔和一点。', N'A small glass pagoda glowing blue and gold at midnight, moonlight on its eaves. For the night owls.', 49, 680, N'盛世华章', N'盛世华章', N'盛世华章', N'十二时辰', N'入门', N'入门款', N'#6274A1', N'stars', N'galaxy', N'pagoda', N'gift-art/oriental/oriental-midnight-pagoda.png', N'gift-art/oriental/oriental-midnight-pagoda.thumb.png', N'gift-art/oriental/oriental-midnight-pagoda.charm.png', 0, N'mall,chat,live,private', 1, 54);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'oriental-dawn-corner-tower', N'卯时·紫气东来', N'Dawn · Purple Clouds', NULL, NULL, N'晨光从宫墙角楼后升起，紫金云霞在屋檐间流动；用清亮的一声早安开启新一天。', N'Morning light rises behind the palace corner tower, purple-gold clouds drifting. A bright good morning.', 69, 880, N'盛世华章', N'盛世华章', N'盛世华章', N'十二时辰', N'入门', N'入门款', N'#8E6795', N'orbit', N'galaxy', N'dawn', N'gift-art/oriental/oriental-dawn-corner-tower.png', N'gift-art/oriental/oriental-dawn-corner-tower.thumb.png', N'gift-art/oriental/oriental-dawn-corner-tower.charm.png', 0, N'mall,chat,live,private', 1, 55);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'oriental-noon-golden-cup', N'午时·日光耀金', N'Noon · Golden Cup', NULL, NULL, N'正午阳光照在鎏金杯盏上，杯沿折出几道明快光线；送给忙到中午也记得停下歇息的朋友。', N'Midday sun on a gilded cup, bright rays off its rim. For friends who remember to pause at lunch.', 99, 1200, N'盛世华章', N'盛世华章', N'盛世华章', N'十二时辰', N'入门', N'入门款', N'#D19D44', N'stars', N'galaxy', N'noon', N'gift-art/oriental/oriental-noon-golden-cup.png', N'gift-art/oriental/oriental-noon-golden-cup.thumb.png', N'gift-art/oriental/oriental-noon-golden-cup.charm.png', 0, N'mall,chat,live,private', 1, 56);
INSERT INTO dbo.Gifts(Id, Name, NameEn, LiveName, LiveNameEn, Description, DescriptionEn, Beans, MallPriceRm, Category, LiveCategory, Series, Subseries, Tier, Rarity, Accent, Effect, LiveEffect, OrientalEffect, ArtFull, ArtThumb, ArtCharm, Wearable, Contexts, Enabled, SortOrder) VALUES (N'oriental-dusk-goose', N'酉时·晚霞落雁', N'Dusk · Homing Geese', NULL, NULL, N'晚霞染红飞檐，归雁掠过层层绛色云彩；在一天将尽时，把温柔的问候送给惦念的人。', N'Sunset reddens the eaves as geese fly home. A gentle hello at the end of the day.', 79, 980, N'盛世华章', N'盛世华章', N'盛世华章', N'十二时辰', N'入门', N'入门款', N'#B45E59', N'hearts', N'heart', N'dusk', N'gift-art/oriental/oriental-dusk-goose.png', N'gift-art/oriental/oriental-dusk-goose.thumb.png', N'gift-art/oriental/oriental-dusk-goose.charm.png', 0, N'mall,chat,live,private', 1, 57);
