INSERT INTO dbo.GiftBackgrounds(Id, Name, NameEn, Description, DescriptionEn, Kind, Tone, Ink, Css, Image, Enabled, SortOrder) VALUES (N'crimson-gold', N'暗红鎏金', N'Crimson & Gold', N'深红底色浮着细腻金光，让礼物陈列多一份温暖的仪式感。', N'Deep red with a fine golden glow, for a display with a touch of ceremony.', N'gradient', N'dark', N'#FFFFFF', N'radial-gradient(ellipse at 18% 10%, rgba(224,181,99,0.24) 0%, transparent 44%), radial-gradient(ellipse at 88% 78%, rgba(145,41,48,0.48) 0%, transparent 55%), linear-gradient(145deg, #36171C 0%, #5B202A 48%, #28171B 100%)', NULL, 1, 0);
INSERT INTO dbo.GiftBackgrounds(Id, Name, NameEn, Description, DescriptionEn, Kind, Tone, Ink, Css, Image, Enabled, SortOrder) VALUES (N'rose-mist', N'红粉晨雾', N'Rose Mist', N'像清晨花瓣上的薄雾，轻轻衬出每一份柔软心意。', N'Like morning mist on petals: a soft backdrop for tender gifts.', N'gradient', N'light', N'#512F3C', N'radial-gradient(ellipse at 16% 12%, rgba(255,255,255,0.90) 0%, transparent 52%), radial-gradient(ellipse at 90% 80%, rgba(241,172,189,0.35) 0%, transparent 52%), linear-gradient(145deg, #FFF5F5 0%, #FCE7EC 56%, #F5DCE2 100%)', NULL, 1, 1);
INSERT INTO dbo.GiftBackgrounds(Id, Name, NameEn, Description, DescriptionEn, Kind, Tone, Ink, Css, Image, Enabled, SortOrder) VALUES (N'mint-light', N'薄荷浅绿', N'Fresh Mint', N'浅浅薄荷色配上明亮留白，把收藏角装点得清新自在。', N'Pale mint with plenty of light, for a fresh and easy corner.', N'gradient', N'light', N'#27483A', N'radial-gradient(ellipse at 20% 15%, rgba(255,255,255,0.95) 0%, transparent 48%), radial-gradient(ellipse at 80% 82%, rgba(179,221,204,0.35) 0%, transparent 50%), linear-gradient(145deg, #F2FBF5 0%, #E3F3EA 54%, #D4EADF 100%)', NULL, 1, 2);
INSERT INTO dbo.GiftBackgrounds(Id, Name, NameEn, Description, DescriptionEn, Kind, Tone, Ink, Css, Image, Enabled, SortOrder) VALUES (N'midnight-stars', N'午夜星空', N'Midnight Stars', N'安静的蓝紫夜幕托起点点星光，适合慢慢欣赏闪耀的小收藏。', N'A quiet blue-violet night sky, dotted with stars.', N'gradient', N'dark', N'#FFFFFF', N'radial-gradient(circle at 17% 21%, rgba(255,244,206,0.9) 0 1px, transparent 2px), radial-gradient(circle at 74% 16%, rgba(237,236,255,0.85) 0 1px, transparent 2px), radial-gradient(circle at 86% 62%, rgba(224,230,255,0.7) 0 1px, transparent 2px), radial-gradient(ellipse at 68% 36%, rgba(102,84,166,0.38) 0%, transparent 52%), linear-gradient(160deg, #111829 0%, #22213D 54%, #101722 100%)', NULL, 1, 3);
INSERT INTO dbo.GiftBackgrounds(Id, Name, NameEn, Description, DescriptionEn, Kind, Tone, Ink, Css, Image, Enabled, SortOrder) VALUES (N'kl-night', N'吉隆坡夜色', N'KL by Night', N'把熟悉的城市灯火留在身后，让每一次相遇都有温暖的夜色相伴。', N'The city lights you know, glowing warmly behind you.', N'photo', N'dark', N'#FFFFFF', N'', N'city-kl.jpg', 1, 4);
INSERT INTO dbo.GiftBackgrounds(Id, Name, NameEn, Description, DescriptionEn, Kind, Tone, Ink, Css, Image, Enabled, SortOrder) VALUES (N'cream-solid', N'奶油纯色', N'Plain Cream', N'柔和奶油底色安静退后，让礼物本身的色彩成为主角。', N'A soft cream tone that steps back and lets your gifts shine.', N'gradient', N'light', N'#493E32', N'linear-gradient(0deg, #F8F1E6 0%, #F8F1E6 100%)', NULL, 1, 5);
